import { CLASSES, DEFAULT_QUESTIONS, SUPPORT_CLASSES, DAMAGE_FLAVOR, PUZZLE_SYMBOLS } from './config.js';
import { updateData, getData, listenData, setupDisconnect } from './firebase.js';
import { showView, show, hide, setText, setHTML, setStyle, getInputValue, toggleVisible, setDisabled, setTargetingMode, makeRosterTargetable, clearRosterTargetable } from './ui.js';
import { shake, flash, hitMarker, spawnDamage, notify, showReceivedEffect, showLowHpWarning, pulseRosterCard, showSupportAction, showBossWarning, hideBossWarning, getFlavorText } from './juice.js';
import { incrementCombo, breakCombo, getComboMult } from './combo.js';

// Player state
let roomCode = null;
let playerId = null;
let playerName = null;
let playerClass = null;
let localState = null;
let currentQuestion = null;
let deathQuestion = null;
let isDeadLocal = false;
let deathStreak = 0;
let specialCooldown = 0;
let isInputLocked = false;

// Targeting state
let isTargetingMode = false;
let pendingAbility = null;

// Track previous state for detecting incoming effects
let prevHealth = null;
let prevShield = null;
let prevBuff = null;

// Boss attack state
let lastBossAttackTimestamp = 0;
let currentBossWarning = null;

/**
 * Get player's room code
 */
export function getRoomCode() {
    return roomCode;
}

/**
 * Get player's local state
 */
export function getLocalState() {
    return localState;
}

/**
 * Check if player is dead
 */
export function isDead() {
    return isDeadLocal;
}

/**
 * Apply class-specific theming to the game container
 * @param {string} cls - Class name (WARRIOR, GUARDIAN, MEDIC, TACTICIAN)
 */
function applyClassTheme(cls) {
    const gameContainer = document.querySelector('.game-container');
    if (!gameContainer) return;
    
    // Remove any existing class themes
    gameContainer.classList.remove('class-themed', 'warrior', 'guardian', 'medic', 'tactician');
    
    // Add new class theme
    gameContainer.classList.add('class-themed', cls.toLowerCase());
}

/**
 * Attempt to join a game lobby
 */
export async function joinLobby() {
    const name = getInputValue('input-name');
    const code = getInputValue('input-room');
    
    if (!name || code.length !== 6) {
        alert('Enter name and 6-digit code');
        return false;
    }
    
    try {
        const gameData = await getData(`games/${code}`);
        if (gameData) {
            roomCode = code;
            playerName = name;
            showView('view-class-select');
            return true;
        } else {
            alert('Room not found');
            return false;
        }
    } catch (e) {
        alert('Connection error');
        return false;
    }
}

