/**
 * Check if a player is targeted by current boss attack
 * @param {Object} bossAttack - Boss attack data
 * @param {string} checkPlayerId - Player ID to check
 * @returns {boolean}
 */
function isPlayerTargeted(bossAttack, checkPlayerId) {
    if (!bossAttack?.targets) return false;
    if (bossAttack.type === 'aoe') return true;
    return bossAttack.targets.some(t => t.id === checkPlayerId);
}

/**
 * Handle boss attack warnings and effects
 * @param {Object} bossAttack - Boss attack data from Firebase
 */
function handleBossAttack(bossAttack) {
    // No attack or attack cleared
    if (!bossAttack || !bossAttack.timestamp) {
        if (currentBossWarning) {
            hideBossWarning();
            currentBossWarning = null;
        }
        return;
    }
    
    // Already processed this attack
    if (bossAttack.timestamp === lastBossAttackTimestamp) {
        return;
    }
    
    lastBossAttackTimestamp = bossAttack.timestamp;
    currentBossWarning = bossAttack;
    
    // Check if this is an enrage notification (legacy)
    if (bossAttack.type === 'enrage') {
        showBossWarning(bossAttack.warningText, bossAttack.icon, 0, false);
        flash('#ff4757', 500);
        shake('heavy');
        notify('BOSS ENRAGED!', 'crit', '2x DAMAGE');
        return;
    }
    
    // Check if this is a phase change notification
    if (bossAttack.type === 'phase_change') {
        const phase = bossAttack.phase;
        const color = phase === 'DESPERATE' ? '#ff4757' : '#ffa502';
        
        showBossWarning(bossAttack.warningText, bossAttack.icon, 0, false);
        flash(color, 500);
        shake('heavy');
        
        if (phase === 'DESPERATE') {
            notify('BOSS IS DESPERATE!', 'crit', 'TARGETING WEAKEST');
        } else {
            notify('BOSS ENRAGED!', 'crit', '+50% SPEED');
        }
        return;
    }
    
    // Check if this is a timer enrage notification
    if (bossAttack.type === 'timer_enrage') {
        showBossWarning(bossAttack.warningText, bossAttack.icon, 0, false);
        flash('#ff4757', 800);
        shake('heavy');
        notify('TIME EXPIRED!', 'crit', '2x DAMAGE & SPEED');
        return;
    }
    
    // Check if player is targeted
    const isTargeted = isPlayerTargeted(bossAttack, playerId);
    const timeUntilHit = bossAttack.resolveAt - Date.now();
    
    // Build target list text
    let targetText = '';
    if (bossAttack.type === 'aoe') {
        targetText = 'ALL PLAYERS';
    } else if (bossAttack.targets) {
        targetText = bossAttack.targets.map(t => t.name).join(', ');
    }
    
    // Show warning
    showBossWarning(
        `${bossAttack.warningText}: ${targetText}`,
        bossAttack.icon,
        Math.max(0, timeUntilHit),
        isTargeted
    );
    
    // Extra feedback if targeted
    if (isTargeted) {
        flash('#ff4757', 200);
        shake();
        notify(`${bossAttack.icon} INCOMING ATTACK!`, 'crit', `${Math.ceil(timeUntilHit / 1000)}s`);
    }
}

