/**
 * Detect incoming support effects by comparing with previous state
 * @param {Object} me - Current player data
 */
function detectIncomingEffects(me) {
    // Skip on first render (no previous state)
    if (prevHealth === null) {
        prevHealth = me.health;
        prevShield = me.shield || 0;
        prevBuff = me.buff;
        return;
    }
    
    const currentShield = me.shield || 0;
    const currentBuff = me.buff;
    
    // Detect heal (health increased, but not from revive)
    if (me.health > prevHealth && prevHealth > 0) {
        const healAmount = me.health - prevHealth;
        // Only show if it's a significant heal (not just rounding)
        if (healAmount >= 100) {
            showReceivedEffect('heal', 'ALLY', healAmount);
            pulseRosterCard(playerId, 'heal');
        }
    }
    
    // Detect new shield (shield increased)
    if (currentShield > prevShield) {
        const shieldAmount = currentShield - prevShield;
        showReceivedEffect('shield', 'ALLY', shieldAmount);
        pulseRosterCard(playerId, 'shield');
    }
    
    // Detect new buff (buff appeared or changed)
    if (currentBuff && currentBuff.damageBonus && (!prevBuff || !prevBuff.damageBonus)) {
        const sourceName = currentBuff.source || 'ALLY';
        showReceivedEffect('buff', sourceName, null);
        pulseRosterCard(playerId, 'buff');
    }
    
    // Update previous state
    prevHealth = me.health;
    prevShield = currentShield;
    prevBuff = currentBuff;
}

/**
 * Initialize death state
 */
function initDeath() {
    isDeadLocal = true;
    deathStreak = 0;
    show('view-death-overlay');
    updateDeathUI();
    loadDeathQuestion();
}

/**
 * Revive from death
 */
function revive() {
    isDeadLocal = false;
    hide('view-death-overlay');
}

/**
 * Load a question for the death screen
 */
function loadDeathQuestion() {
    const questions = localState?.questions || DEFAULT_QUESTIONS;
    const q = questions[Math.floor(Math.random() * questions.length)];
    deathQuestion = q;
    
    setText('death-question-text', q.text);
    document.querySelectorAll('#death-answers-grid .answer-btn').forEach((btn, i) => {
        btn.innerText = q.answers[i];
    });
}

/**
 * Handle answer during death state
 * @param {number} idx - Answer index
 */
async function handleDeathAnswer(idx) {
    if (idx === deathQuestion.correct) {
        deathStreak++;
        flash('#2ed573', 150);
        updateDeathUI();
        
        if (deathStreak >= 3) {
            // Revive at 50% health
            const me = localState?.players?.[playerId];
            if (me) {
                await updateData(`games/${roomCode}/players/${playerId}`, {
                    health: Math.floor(me.maxHealth * 0.5)
                });
                
                // Immediately revive and return to game
                revive();
                loadQuestion();
            }
        } else {
            loadDeathQuestion();
        }
    } else {
        deathStreak = 0;
        flash('#ff4757', 200);
        shake();
        updateDeathUI();
        loadDeathQuestion();
    }
}

/**
 * Update death screen progress UI
 */
function updateDeathUI() {
    [1, 2, 3].forEach(i => {
        const seg = document.getElementById(`reboot-seg-${i}`);
        if (seg) {
            seg.style.background = i <= deathStreak ? '#3742fa' : '#1a1a2e';
            seg.style.boxShadow = i <= deathStreak ? '0 0 10px #3742fa' : 'none';
        }
    });
}

