/**
 * Update puzzle timer display
 * @param {Object} puzzle - Puzzle data
 */
function updatePuzzleTimer(puzzle) {
    if (puzzleTimerInterval) {
        clearInterval(puzzleTimerInterval);
    }
    
    const update = () => {
        const elapsed = Date.now() - puzzle.startTime;
        const remaining = Math.max(0, puzzle.timeLimit - elapsed);
        const seconds = Math.ceil(remaining / 1000);
        
        const timerEl = document.getElementById('puzzle-timer-player');
        if (timerEl) {
            timerEl.textContent = seconds;
            timerEl.classList.toggle('timer-critical', seconds <= 10);
        }
    };
    
    update();
    puzzleTimerInterval = setInterval(update, 100);
}

/**
 * Handle puzzle input changes
 * @param {string} value - Current input value
 */
export function onPuzzleInput(value) {
    const submitBtn = document.getElementById('btn-submit-puzzle');
    if (submitBtn) {
        submitBtn.disabled = value.length !== 6;
    }
}

/**
 * Submit the puzzle code
 */
export async function submitPuzzleCode() {
    const input = document.getElementById('puzzle-code-input');
    if (!input) return;
    
    const code = input.value.trim();
    if (code.length !== 6) return;
    
    // Send to Firebase for host to validate
    await updateData(`games/${roomCode}/puzzleSubmission`, {
        code: code,
        playerId: playerId,
        playerName: playerName,
        timestamp: Date.now()
    });
    
    // Clear input
    input.value = '';
    onPuzzleInput('');
    
    // Show feedback
    const feedback = document.getElementById('puzzle-feedback');
    if (feedback) {
        feedback.classList.remove('hidden');
        feedback.innerHTML = `<span class="text-gold">Submitted: ${code}</span>`;
    }
    
    flash('#ffa502', 200);
}

// ============================================
// SYMBOL PUZZLE FUNCTIONS
// ============================================

/**
 * Pick a symbol for the symbol puzzle
 * @param {number} symbolId - ID of the symbol picked
 */
export function pickSymbol(symbolId) {
    if (!window.symbolSelection) {
        window.symbolSelection = [null, null, null, null, null, null];
    }
    
    // Find the first empty slot
    const emptyIndex = window.symbolSelection.findIndex(s => s === null);
    if (emptyIndex === -1) return; // All slots full
    
    // Set the symbol
    window.symbolSelection[emptyIndex] = symbolId;
    
    // Update display
    updateSymbolSelectionDisplay();
    
    // Visual feedback
    flash('#ffa502', 100);
}

/**
 * Clear a specific symbol slot
 * @param {number} slotIndex - Index of slot to clear
 */
function clearSymbolSlot(slotIndex) {
    if (!window.symbolSelection) return;
    
    if (window.symbolSelection[slotIndex] !== null) {
        window.symbolSelection[slotIndex] = null;
        updateSymbolSelectionDisplay();
        flash('#3742fa', 100);
    }
}

/**
 * Clear all symbol selections
 */
export function clearSymbolSelection() {
    window.symbolSelection = [null, null, null, null, null, null];
    updateSymbolSelectionDisplay();
    flash('#ff4757', 150);
}

/**
 * Update the symbol selection display
 */
function updateSymbolSelectionDisplay() {
    const slots = document.querySelectorAll('.symbol-slot');
    const submitBtn = document.getElementById('btn-submit-symbols');
    
    let allFilled = true;
    
    slots.forEach((slot, idx) => {
        const symbolId = window.symbolSelection?.[idx];
        const valueEl = slot.querySelector('.symbol-slot-value');
        
        if (symbolId !== null && symbolId !== undefined) {
            const symbolData = PUZZLE_SYMBOLS[symbolId];
            valueEl.textContent = symbolData.symbol;
            slot.classList.add('filled');
        } else {
            valueEl.textContent = '?';
            slot.classList.remove('filled');
            allFilled = false;
        }
    });
    
    // Enable/disable submit button
    if (submitBtn) {
        submitBtn.disabled = !allFilled;
    }
}

/**
 * Submit the symbol code
 */
export async function submitSymbolCode() {
    if (!window.symbolSelection) return;
    
    // Check all slots are filled
    if (window.symbolSelection.some(s => s === null)) return;
    
    // Convert to comma-separated string
    const code = window.symbolSelection.join(',');
    
    // Send to Firebase for host to validate
    await updateData(`games/${roomCode}/puzzleSubmission`, {
        code: code,
        playerId: playerId,
        playerName: playerName,
        timestamp: Date.now()
    });
    
    // Show the symbols submitted
    const symbolsDisplay = window.symbolSelection.map(id => PUZZLE_SYMBOLS[id].symbol).join(' ');
    
    // Show feedback
    const feedback = document.getElementById('puzzle-feedback');
    if (feedback) {
        feedback.classList.remove('hidden');
        feedback.innerHTML = `<span class="text-gold">Submitted: ${symbolsDisplay}</span>`;
    }
    
    // Clear selection for retry
    clearSymbolSelection();
    
    flash('#ffa502', 200);
}

